import java.util.Arrays;
class Playlist {private final String[] songs;private int songCount;public Playlist(int capacity){if(capacity<0)throw new IllegalArgumentException("Capacity cannot be negative");songs=new String[capacity];songCount=0;}public void addSong(String song){if(song==null||songCount>=songs.length){System.out.println("Cannot add song");return;}songs[songCount++]=song;}public String[] getSongs(){return Arrays.copyOf(songs,songCount);}public int getSongCount(){return songCount;}}
public class PlaylistProgram {public static void main(String[] args){Playlist p=new Playlist(10);p.addSong("Song A");p.addSong("Song B");String[] copy=p.getSongs();System.out.println("Songs: "+Arrays.toString(copy));copy[0]="Hacked";System.out.println("After modifying copy: "+Arrays.toString(p.getSongs()));System.out.println("Song count: "+p.getSongCount());}}